  id: i,
  size: seededRandom(i + 1) * 2 + 0.5,
  top: seededRandom(i + 101) * 100,
  left: seededRandom(i + 201) * 100,
  opacity: seededRandom(i + 301) * 0.6 + 0.1,
  duration: seededRandom(i + 401) * 4 + 3,
  delay: seededRandom(i + 501) * 4,
}));

